insert into banglog_plus.legal_source_versions(source_id,version,location,checked_at,effective_date,technical_status,human_legal_review,use_scope,metadata) values('2010da89876','crosschecked-2026-11-03.v1','판결요지·이유·주문','2026-11-03',null,'verified','pending','internal','{"id": "2010da89876", "version": "crosschecked-2026-11-03.v1", "title": "대법원 2012. 6. 14. 선고 2010다89876·89883 · 구조적 결로", "institution": "대법원 / 국가법령정보센터", "url": "https://www.law.go.kr/LSW/precInfoP.do?precSeq=164196", "location": "판결요지·이유·주문", "checkedAt": "2026-11-03", "effectiveDate": null, "technicalStatus": "verified", "humanLegalReview": "pending", "use": "internal", "scope": "가구전시장의 여름형 결로 사건으로 주택 곰팡이의 직접 판결은 아니에요. 구조적 하자와 환기·제습 등 여러 원인, 계약상 용도를 함께 살펴야 해요.", "issues": ["mold"], "verification": {"status": "cross_checked", "checkedAt": "2026-11-03", "caseNumber": "2010다89876, 89883", "decisionDate": "2012-06-14", "primaryUrl": "https://www.law.go.kr/LSW/precInfoP.do?precSeq=164196", "crossCheckUrl": "https://albup.co.kr/page/judgement_detail.php?com_idx=50445", "method": "국가법령정보센터 전문과 다른 제공 사이트의 판결 전문 대조", "checks": ["사건번호", "선고일", "법원", "판결 취지", "적용 한계"], "limitations": "원문·재수록본 또는 공식 해설의 내용 일치 확인. 독립된 법률가 검토·후속 판례 전수 확인은 아님.", "reviewerType": "ai_source_comparison", "humanLegalReview": "pending"}}'::jsonb) on conflict do nothing;
