insert into banglog_plus.legal_source_versions(source_id,version,location,checked_at,effective_date,technical_status,human_legal_review,use_scope,metadata) values('2014na13609','crosschecked-2026-11-03.v1','판결요지·이유·주문','2026-11-03',null,'verified','pending','internal','{"id": "2014na13609", "version": "crosschecked-2026-11-03.v1", "title": "서울중앙지법 2014. 6. 20. 선고 2014나13609 · 곰팡이 통지의무", "institution": "서울중앙지방법원 / 국가법령정보센터", "url": "https://www.law.go.kr/LSW/precInfoP.do?precSeq=174940", "location": "판결요지·이유·주문", "checkedAt": "2026-11-03", "effectiveDate": null, "technicalStatus": "verified", "humanLegalReview": "pending", "use": "internal", "scope": "다가구주택의 결로·곰팡이 사건인 하급심 확정판결이에요. 집주인이 몰랐고 늦은 통지 때문에 수선하지 못한 사정에 관한 판단이며, 알리지 않았다는 이유만으로 모든 권리가 사라진다는 뜻은 아니에요.", "issues": ["mold", "leak"], "verification": {"status": "cross_checked", "checkedAt": "2026-11-03", "caseNumber": "2014나13609", "decisionDate": "2014-06-20", "primaryUrl": "https://www.law.go.kr/LSW/precInfoP.do?precSeq=174940", "crossCheckUrl": "https://whallaw.com/6753", "method": "국가법령정보센터 전문·법원 게시물과 다른 제공 사이트의 판결 전문 대조", "checks": ["사건번호", "선고일", "법원", "판결 취지", "적용 한계"], "limitations": "원문·재수록본 또는 공식 해설의 내용 일치 확인. 독립된 법률가 검토·후속 판례 전수 확인은 아님.", "reviewerType": "ai_source_comparison", "humanLegalReview": "pending", "additionalUrl": "https://seoul.scourt.go.kr/dcboard/new/DcNewsViewAction.work?cbub_code=000210&gubun=44&pageIndex=1&scode_kname=&searchWord=&seqnum=13224"}}'::jsonb) on conflict do nothing;
insert into banglog_plus.knowledge_chunks(id,dataset_version,source_id,source_version,claim_id,claim,content,issues,keywords,observations) values('maintenance-principle','repair-kb-2026-11-03.v2','civil-623','2026-03-17.checked-2026-10-21','maintenance','임대인은 계약 기간 동안 주택을 사용·수익하는 데 필요한 상태를 유지할 의무가 있다는 일반 원칙이 있어요.','임대인이 목적물을 사용·수익에 필요한 상태로 유지할 의무가 있다는 일반 원칙을 다룬 조문 요약입니다. 고장 원인이나 모든 수리비의 귀속을 이 조문만으로 확정하지 않습니다.',array['mold','leak','boiler','surface','drain','fixture']::text[],array['수리','고장','누수','곰팡이','보일러','배수']::text[],array[]::text[]) on conflict do nothing;
insert into banglog_plus.knowledge_chunks(id,dataset_version,source_id,source_version,claim_id,claim,content,issues,keywords,observations) values('repair-scope','repair-kb-2026-11-03.v2','easylaw-repair','checked-2026-10-21','scope','수선의무 범위는 사용에 미치는 영향과 수리의 정도, 계약 조건 등을 함께 확인해야 해요.','공식 생활법령의 수선의무 설명을 정리한 자료입니다. 사용·수익에 미치는 영향, 수리 정도, 계약 문구와 실제 원인을 함께 확인합니다. 세입자 설명과 전달받은 점검 의견을 검증된 원인으로 바꾸지 않습니다.',array['mold','leak','boiler','surface','drain','fixture']::text[],array['계약','특약','점검','노후','원인','수선']::text[],array[]::text[]) on conflict do nothing;
insert into banglog_plus.knowledge_chunks(id,dataset_version,source_id,source_version,claim_id,claim,content,issues,keywords,observations) values('initial-state-restoration','repair-kb-2026-11-03.v2','2023da249661','crosschecked-2026-11-03.v1','initial-state','입주 당시 상태와 원상회복 약정을 확인할 필요가 있어요. 참고 판결은 이전 임차인의 시설이 있던 토지 사건으로, 주택 벽지·장판 비용을 직접 정한 판결은 아니에요.','2023다249661은 토지 임대 당시 이미 있던 종전 임차인의 시설 철거가 쟁점입니다. 임차 당시 상태로 반환하는 것이 원칙이나 계약 체결 경위와 내용 등 특별한 사정을 개별적으로 판단합니다. 통상 마모 금액이나 벽지 교체비 비율을 정한 판결은 아닙니다.',array['surface']::text[],array['벽지','장판','찍힘','찢어','원상회복','입주']::text[],array['wall-tear','wall-dent','floor-tear','floor-dent']::text[]) on conflict do nothing;
insert into banglog_plus.knowledge_chunks(id,dataset_version,source_id,source_version,claim_id,claim,content,issues,keywords,observations) values('equipment-cause-and-control','repair-kb-2026-11-03.v2','2018da291347','crosschecked-2026-11-03.v1','equipment-cause','제품 고장의 원인과 관리 영역을 확인해야 해요. 참고 판결은 임대 장비 반환 시 훼손 사건으로, 임대인의 수선의무만으로 최종 손해배상책임을 정하지 않아요.','2018다291347은 임대 장비의 반환 시 훼손과 손해배상 사건입니다. 임차인이 책임질 수 없는 사유의 증명 및 임대인의 지배·관리 영역에 있는 하자 여부를 심리해야 한다는 취지입니다. 원인 불명만으로 임차인이 면책되는 것은 아니며 주택 옵션 가전의 직접 사건도 아닙니다.',array['fixture','boiler']::text[],array['냉장고','세탁기','에어컨','보일러','옵션','노후','과실']::text[],array[]::text[]) on conflict do nothing;
insert into banglog_plus.knowledge_chunks(id,dataset_version,source_id,source_version,claim_id,claim,content,issues,keywords,observations) values('major-repair-special-agreement','repair-kb-2026-11-03.v2','94da34692','crosschecked-2026-11-03.v1','major-repair-special-agreement','대규모 설비 수선인지와 특약의 구체적인 범위를 함께 확인해야 해요. 참고 판결은 여관의 노후 배관·보일러 사건이에요.','노후 배관과 보일러 때문에 여관 운영에 큰 지장이 생긴 사건이다. 수선 부담에 관한 특약이 있었지만 그 범위가 구체적이지 않았고 전면 교체가 필요한 사정 등을 고려해 임대인의 책임을 인정한 원심을 유지했다. 간단한 수리와 주요 설비의 대규모 수선을 구별한 판결이며 모든 특약이 무효라는 뜻은 아니다.',array['boiler','leak','drain','fixture']::text[],array['배관','보일러','노후','교체','특약','누수','수선']::text[],array[]::text[]) on conflict do nothing;
insert into banglog_plus.knowledge_chunks(id,dataset_version,source_id,source_version,claim_id,claim,content,issues,keywords,observations) values('condensation-structure-and-use','repair-kb-2026-11-03.v2','2010da89876','crosschecked-2026-11-03.v1','condensation-structure-and-use','결로는 건물 구조와 사용 상태를 함께 점검해야 해요. 가구전시장 사건에서는 단열·방습 문제와 사용자의 조치를 구분해 판단했어요.','가구전시장 바닥의 결로에 관해 단열·방습 미비와 계약상 용도를 살피지 않고 임대인의 책임을 배척한 원심을 일부 파기환송했다. 임차인의 환기·제습 미흡도 손해배상 범위를 제한하는 사정으로 보았다. 주택 곰팡이가 모두 건물 하자라는 결론이나 배상 비율을 정한 자료로 사용하지 않는다.',array['mold']::text[],array['곰팡이','결로','단열','방습','환기','제습','구조']::text[],array[]::text[]) on conflict do nothing;
insert into banglog_plus.knowledge_chunks(id,dataset_version,source_id,source_version,claim_id,claim,content,issues,keywords,observations) values('prompt-notice-and-loss','repair-kb-2026-11-03.v2','2014na13609','crosschecked-2026-11-03.v1','prompt-notice-and-loss','하자를 발견한 시점과 집주인에게 알린 내용을 기록해 두세요. 참고 판결은 통지가 늦어 수선하지 못한 경우 손해배상 범위가 제한될 수 있음을 다뤘어요.','다가구주택에서 결로와 곰팡이로 손해가 발생했으나 임대인에게 제때 알렸다는 증명이 부족했던 사건이다. 임대인이 하자를 몰라 수선하지 못한 범위에서는 책임을 제한하고, 신속히 알렸어도 막을 수 없었던 기존 손해를 구별했다. 임차인의 항소가 기각되었다. 사진·발견일·통지와 답변 기록의 필요성을 설명하는 참고 자료이며 문자 통지만이 유효하다는 뜻은 아니다.',array['mold','leak']::text[],array['곰팡이','결로','통지','연락','문자','손해','물방울']::text[],array[]::text[]) on conflict do nothing;
